def split_source_amounts(expense: Expense) -> tuple[SplitEntry, ...]:
    from decimal import Decimal, getcontext

    getcontext().prec = 50  # Set local precision to 50

    if expense.split_kind == SplitKind.AMOUNTS:
        return expense.entries  # Return entries unchanged

    entries = list(expense.entries)
    total_entries = len(entries)
    total_shares = sum(entry.value for entry in entries) if expense.split_kind == SplitKind.SHARES else None

    if expense.split_kind == SplitKind.PERCENTAGES:
        return tuple(
            SplitEntry(member_id=entry.member_id, value=(expense.amount * entry.value / Decimal(100)))
            for entry in entries
        )

    elif expense.split_kind == SplitKind.EQUAL:
        equal_value = expense.amount / Decimal(total_entries)
        return tuple(SplitEntry(member_id=entry.member_id, value=equal_value) for entry in entries)

    elif expense.split_kind == SplitKind.SHARES:
        return tuple(
            SplitEntry(member_id=entry.member_id, value=(expense.amount * entry.value / total_shares))
            for entry in entries
        )

    raise ValueError("Unsupported split kind")

