def settle_up(balances: dict[str, int]) -> tuple[Transfer, ...]:
    from itertools import combinations, chain

    nonzero_balances = {member_id: cents for member_id, cents in balances.items() if cents != 0}

    if sum(nonzero_balances.values()) != 0:
        raise ValueError('unbalanced')
    if len(nonzero_balances) > MAX_SETTLEMENT_MEMBERS:
        raise ValueError('too many members')

    debtors = sorted((member_id, -cents) for member_id, cents in nonzero_balances.items() if cents < 0)
    creditors = sorted((member_id, cents) for member_id, cents in nonzero_balances.items() if cents > 0)

    def get_zero_sum_partitions(elements):
        if len(elements) == 0:
            return [[]]
        result = []
        for i in range(len(elements)):
            for sub_partition in get_zero_sum_partitions(elements[i + 1:]):
                result.append([[elements[i]]] + sub_partition)
                for j in range(len(sub_partition)):
                    result.append([[elements[i]] + sub_partition[j]] + sub_partition[:j] + sub_partition[j + 1:])
        return result

    all_partitions = get_zero_sum_partitions(list(nonzero_balances.keys()))
    valid_partitions = []

    for partition in all_partitions:
        group_sums = [sum(nonzero_balances[k] for k in group) for group in partition]
        if all(s == 0 for s in group_sums):
            valid_partitions.append(partition)

    if not valid_partitions:
        return ()

    valid_partitions.sort(key=lambda gs: (len(gs), gs))
    selected_groups = valid_partitions[0]

    transfers = []
    for group in selected_groups:
        group_debtors = sorted((member_id, -nonzero_balances[member_id]) for member_id in group if nonzero_balances[member_id] < 0)
        group_creditors = sorted((member_id, nonzero_balances[member_id]) for member_id in group if nonzero_balances[member_id] > 0)

        d_index, c_index = 0, 0
        while d_index < len(group_debtors) and c_index < len(group_creditors):
            debtor_id, debt = group_debtors[d_index]
            creditor_id, credit = group_creditors[c_index]

            transfer_amount = min(debt, credit)
            transfers.append(Transfer(debtor_id, creditor_id, transfer_amount))

            nonzero_balances[debtor_id] += transfer_amount
            nonzero_balances[creditor_id] -= transfer_amount

            if nonzero_balances[debtor_id] == 0:
                d_index += 1
            if nonzero_balances[creditor_id] == 0:
                c_index += 1

    return tuple(sorted(transfers, key=lambda t: (t.from_member_id, t.to_member_id, t.cents)))
